{"action":"run_code","code":"const issues = [];
for (let page = 1; page <= 20; page++) {
  const result = await tools.list_issues({ repo: "acme/web", state: "open", label: "perf", page });
  const items = result.items ?? [];
  issues.push(...items);
  if (items.length < 50) break;
}
const targets = issues.filter(issue => issue.assignee?.login);
for (const issue of targets) {
  await tools.post_comment({
    repo: "acme/web",
    number: issue.number,
    body: `ping @${issue.assignee.login}`
  });
}
return { posted: targets.length };","answer":""}

